SELECT URGT.URIDD YMD, UMST.SHNCD SHNCD, SHMV.GENZSHNNMRYAKUSHO GENZSHNNMRYAKUSHO, SHMV.SHINSHNNMRYAKUSHO SHINSHNNMRYAKUSHO, SHMV.IRO IRO, SHMV.SZNM SZNM, UMST.KATASIKI KATASIKI, SYKM.MOJISETTEIATAI MOJISETTEIATAI, UMST.SURYO SURYO, SHMV.URITRTSKITANINM URITRTSKITANINM, SHMV.URIIRISU URIIRISU, NVL(UMST.SURYO,0) * NVL(SHMV.URIIRISU,0) SOKAZU, UMST.UNT UNT, UMST.KIN KIN, UMST.SHOHITAXKIN SHOHITAXKIN, UMST.SANKOUSHOHITAXKIN SANKOUSHOHITAXKIN, NVL(UMST.KIN,0) + NVL(UMST.SHOHITAXKIN,0) + NVL(UMST.SANKOUSHOHITAXKIN,0) SANKOUTAXKOMIURIKIN, NULL NYKNKIN, NULL NEBIKIKIN, NULL TESURYO, UMST.MEISAIBIKO BIKO, UMST.URIDNPYNO PYNO, URGT.EDANO EDANO, UMST.URIDNPYMEISAINO MEISAINO, UMST.LCTGRYCD LCTGRYCD, UMST.MCTGRYCD MCTGRYCD, UMST.SCTGRYCD SCTGRYCD, SCGM.LCTGRYNM LCTGRYNM, SHMV.SHNNMKIRIKAEDD SHNNMKIRIKAEDD, URGT.SKYSHIMEDYDM SKYSHIMEDYDM, URGT.SKYSHIMEDD SKYSHIMEDD, URGT.GETSUJISHIMEDYDM GETSUJISHIMEDYDM, URGT.GETSUJISHIMEDD GETSUJISHIMEDD, UMST.INPTSYSTMYMD INPTSYSTMYMD, UMST.INPTSYSTMJIKAN INPTSYSTMJIKAN, UMST.TOSHAAPKIHONCD TOSHAAPKIHONCD, UMST.TOSHASHOPCD TOSHASHOPCD, UMST.TOSHACD TOSHACD, TTSM.TNSHAMEI TNSHAMEI, NULL MOJISETTEIATAI2, URGT.SKYSHOOTPTARINASHIKBN SKYSHOOTPTARINASHIKBN, NULL SKYSAKICD, YHPT.URIAGE_POINT URIPOINT, YHPT.TOKUBETSU_POINT TKBTPOINT, YHPT.POINT_WAKU POINTUTWK, NVL(YHPT.URIAGE_POINT,0) + NVL(YHPT.TOKUBETSU_POINT,0) AS SMPOINT, YHPT.POINT_RENKEI_DD POINTRENKEIDD FROM S06T001T URGT INNER JOIN S06T002T UMST ON URGT.APKIHONCD = UMST.APKIHONCD AND URGT.SHOPCD = UMST.SHOPCD AND URGT.URIDNPYNO = UMST.URIDNPYNO AND URGT.EDANO = UMST.EDANO LEFT JOIN S02V001T SHMV ON UMST.APKIHONCD = SHMV.APKIHONCD AND UMST.SHOPCD = SHMV.SHOPCD AND UMST.SHNCD = SHMV.SHNCD LEFT JOIN S02M036T SCGM ON UMST.LCTGRYCD = SCGM.LCTGRYCD AND SCGM.MCTGRYCD = '000' AND SCGM.SCTGRYCD = '000' LEFT JOIN S02M006T SYKM ON UMST.KEIJOKBN = SYKM.SETTEICD AND SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.SETTEINO = '009' AND SYKM.RCRDKBN = 'M' LEFT JOIN S02M003T TTSM ON UMST.TOSHAAPKIHONCD = TTSM.APKIHONCD AND UMST.TOSHASHOPCD = TTSM.SHOPCD AND UMST.TOSHACD = TTSM.TNSHACD LEFT OUTER JOIN ( SELECT T1.APKIHONCD, T1.SHOPCD, T1.URIDNPYNO, T2.URIDNPYMEISAINO, T2.URIDNPYMEISAIEDANO, SUM(CASE WHEN T2.POINTKIND = '1' THEN NVL(T2.POINTSU, 0) ELSE 0 END) AS URIAGE_POINT, SUM(CASE WHEN T2.POINTKIND IN ('2','10','20','23','24','25') THEN NVL(T2.POINTSU, 0) ELSE 0 END) AS TOKUBETSU_POINT, MAX(CASE WHEN T2.POINTKIND IN ('1','2','10','20','23','24','25') THEN NULLIF(T2.POINTMYAQUARENKEIDD, '') ELSE NULL END) AS POINT_RENKEI_DD, LISTAGG( CASE WHEN T2.POINTKIND IN ('2','10') THEN 'まとめ買い:' || TO_CHAR(NVL(T2.POINTSU, 0)) WHEN T2.POINTKIND = '20' THEN '入会時特典:' || TO_CHAR(NVL(T2.POINTSU, 0)) WHEN T2.POINTKIND = '23' THEN '配達日:' || TO_CHAR(NVL(T2.POINTSU, 0)) WHEN T2.POINTKIND = '24' THEN '時間なし:' || TO_CHAR(NVL(T2.POINTSU, 0)) WHEN T2.POINTKIND = '25' THEN 'MyAqua注文:' || TO_CHAR(NVL(T2.POINTSU, 0)) ELSE NULL END, ',' ) WITHIN GROUP (ORDER BY T2.POINTKIND) AS POINT_WAKU FROM S20T001T T1 INNER JOIN S20T002T T2 ON T1.APKIHONCD = T2.APKIHONCD AND T1.SHOPCD = T2.SHOPCD AND T1.KANRINO = T2.KANRINO GROUP BY T1.APKIHONCD, T1.SHOPCD, T1.URIDNPYNO, T2.URIDNPYMEISAINO, T2.URIDNPYMEISAIEDANO ) YHPT ON YHPT.APKIHONCD = UMST.APKIHONCD AND YHPT.SHOPCD = UMST.SHOPCD AND YHPT.URIDNPYNO = UMST.URIDNPYNO AND YHPT.URIDNPYMEISAINO = UMST.URIDNPYMEISAINO AND YHPT.URIDNPYMEISAIEDANO = UMST.URIDNPYMEISAIEDANO WHERE URGT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND URGT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND URGT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND URGT.GETSUJISHIMEDYDM = #{getsujishimedydm,jdbcType=VARCHAR}
AND URGT.GETSUJIPRCSJISSIDD = '00000000'
AND UMST.NYURYOKUMEISAIFLG = '1'
AND (URGT.URIDD BETWEEN #{stnykndd,jdbcType=VARCHAR} AND #{ednykndd,jdbcType=VARCHAR})
