SELECT NMST.NYKNDD YMD, NULL SHNCD, NULL GENZSHNNMRYAKUSHO, NULL SHINSHNNMRYAKUSHO, NULL IRO, NULL SZNM, NULL KATASIKI, NULL MOJISETTEIATAI, NULL SURYO, NULL URITRTSKITANINM, NULL URIIRISU, NULL SOKAZU, NULL UNT, NULL KIN, NULL SHOHITAXKIN, NULL SANKOUSHOHITAXKIN, NULL SANKOUTAXKOMIURIKIN, NMST.NYKNKIN NYKNKIN, NMST.NEBIKIKIN NEBIKIKIN, NMST.TESURYO TESURYO, NMST.BIKO BIKO, NMST.DNPYNO PYNO, NULL EDANO, 1 MEISAINO, NULL LCTGRYCD, NULL MCTGRYCD, NULL SCTGRYCD, NULL LCTGRYNM, NULL SHNNMKIRIKAEDD, NMST.SKYSHIMEDYDM SKYSHIMEDYDM, NMST.SKYSHIMEDD SKYSHIMEDD, NMST.GETSUJISHIMEDYDM GETSUJISHIMEDYDM, NMST.GETSUJISHIMEDD GETSUJISHIMEDD, NMST.INPTSYSTMYMD INPTSYSTMYMD, NMST.INPTSYSTMJIKAN INPTSYSTMJIKAN, NMST.TOSHAAPKIHONCD TOSHAAPKIHONCD, NMST.TOSHASHOPCD TOSHASHOPCD, NMST.TOSHACD TOSHACD, TTSM.TNSHAMEI TNSHAMEI, SYKM.MOJISETTEIATAI MOJISETTEIATAI2, NMST.SKYSHOOTPTARINASHIKBN SKYSHOOTPTARINASHIKBN, NMST.SKYSAKICD SKYSAKICD, NULL AS URIPOINT, NULL AS TKBTPOINT, NULL AS POINTUTWK, NULL AS SMPOINT, NULL AS POINTRENKEIDD FROM S10T001T NMST LEFT JOIN S02M003T TTSM ON NMST.TOSHAAPKIHONCD = TTSM.APKIHONCD AND NMST.TOSHASHOPCD = TTSM.SHOPCD AND NMST.TOSHACD = TTSM.TNSHACD LEFT JOIN S02M006T SYKM ON NMST.NYKNKIND = SYKM.SETTEICD AND SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.SETTEINO = '050' AND SYKM.RCRDKBN = 'M' WHERE NMST.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND NMST.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND NMST.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
