)) AND (UMST.KEIJOKBN <> '01' AND UMST.KEIJOKBN <> '02' ) THEN UMST.SURYO ELSE 0 END), 0 ) OTHER_1 , NVL(SUM(CASE WHEN UMST.LCTGRYCD = SYKM_1.MOJISETTEIATAI THEN UMST.KIN ELSE 0 END), 0 ) KIN_0 , NVL(SUM(CASE WHEN UMST.LCTGRYCD = SYKM_2.MOJISETTEIATAI OR UMST.LCTGRYCD = SYKM_5.MOJISETTEIATAI THEN UMST.KIN ELSE 0 END),0 ) KIN_1 , NVL(SUM(CASE WHEN UMST.LCTGRYCD <> SYKM_1.MOJISETTEIATAI AND UMST.LCTGRYCD <> SYKM_2.MOJISETTEIATAI AND UMST.LCTGRYCD <> SYKM_5.MOJISETTEIATAI THEN UMST.KIN ELSE 0 END), 0 ) KIN_2 , NVL(SUM(UMST.KIN),0) KIN , 0 NYKNKIN , NVL(URGT.SHOHITAXKIN,0) SHOHITAXKIN FROM S06T001T URGT INNER JOIN S06T002T UMST ON (URGT.APKIHONCD = UMST.APKIHONCD AND URGT.SHOPCD = UMST.SHOPCD AND URGT.URIDNPYNO = UMST.URIDNPYNO AND URGT.EDANO = UMST.EDANO), (SELECT * FROM S02M006T WHERE APKIHONCD = '000' AND SHOPCD = '000' AND RCRDKBN = 'M' AND SETTEINO = '096' AND SETTEICD = '1' )SYKM_1, (SELECT * FROM S02M006T WHERE APKIHONCD = '000' AND SHOPCD = '000' AND RCRDKBN = 'M' AND SETTEINO = '096' AND SETTEICD = '2' )SYKM_2, (SELECT * FROM S02M006T WHERE APKIHONCD = '000' AND SHOPCD = '000' AND RCRDKBN = 'M' AND SETTEINO = '096' AND SETTEICD = '3' )SYKM_5 WHERE URGT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND URGT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND URGT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR} AND URGT.GETSUJIPRCSJISSIDD = '00000000' AND URGT.YUKOKBN = '1' AND UMST.TANPINMEISAIFLG = '1' GROUP BY URGT.APKIHONCD , URGT.SHOPCD , URGT.TOKUISAKICD , URGT.URIDNPYNO , URGT.SHOHITAXKIN ) GROUP BY APKIHONCD , SHOPCD , TOKUISAKICD

SELECT APKIHONCD APKIHONCD, SHOPCD SHOPCD, SKYSAKICD SKYSAKICD, KAISHUHOHOKBN, KAISHUHOHONM, NVL(SUM(REGUAR_0),0) REGUAR_0, NVL(SUM(REGUAR_1),0) REGUAR_1, NVL(SUM(SLIM_0),0) SLIM_0, NVL(SUM(SLIM_1),0) SLIM_1, NVL(SUM(OTHER_0), 0) OTHER_0, NVL(SUM(OTHER_1), 0) OTHER_1, NVL(SUM(KIN_0),0) KIN_0, NVL(SUM(KIN_1),0) KIN_1, NVL(SUM(KIN_2),0) KIN_2, NVL(SUM(KIN),0) KIN, NVL(SUM(SHOHITAXKIN),0) SHOHITAXKIN, NVL(SUM(TAXKOMIURIKEIKIN),0) TAXKOMIURIKEIKIN FROM ( SELECT SKSM.APKIHONCD APKIHONCD, SKSM.SHOPCD SHOPCD, SKSM.SKYSAKICD SKYSAKICD, SKSM.KAISHUHOHOKBN, CONM.ITEMNM KAISHUHOHONM, NVL(SUM( CASE WHEN UMST.LCTGRYCD = SYKM_1.MOJISETTEIATAI AND UMST.SHNCD IN
