)) AND (UMST.KEIJOKBN = '01' OR UMST.KEIJOKBN = '02') AND UMST.TANPINMEISAIFLG = '1' THEN UMST.SURYO ELSE 0 END), 0) OTHER_0, NVL(SUM( CASE WHEN(( UMST.LCTGRYCD = SYKM_1.MOJISETTEIATAI AND UMST.SHNCD NOT IN
#{regshncdlist}
) AND ( UMST.LCTGRYCD = SYKM_1.MOJISETTEIATAI AND UMST.SHNCD NOT IN
