)) AND (UMST.KEIJOKBN <> '01' AND UMST.KEIJOKBN <> '02') AND UMST.TANPINMEISAIFLG = '1' THEN UMST.SURYO ELSE 0 END), 0) OTHER_1, NVL(SUM( CASE WHEN UMST.LCTGRYCD = SYKM_1.MOJISETTEIATAI AND UMST.TANPINMEISAIFLG = '1' THEN UMST.KIN ELSE 0 END ), 0) KIN_0,
NVL(SUM( CASE WHEN (UMST.LCTGRYCD = SYKM_2.MOJISETTEIATAI OR UMST.LCTGRYCD = SYKM_5.MOJISETTEIATAI) AND UMST.TANPINMEISAIFLG = '1' THEN UMST.KIN ELSE 0 END ), 0) KIN_1,
NVL(SUM( CASE WHEN UMST.LCTGRYCD <> SYKM_1.MOJISETTEIATAI AND UMST.LCTGRYCD <> SYKM_2.MOJISETTEIATAI AND UMST.LCTGRYCD <> SYKM_5.MOJISETTEIATAI AND UMST.TANPINMEISAIFLG = '1' THEN UMST.KIN ELSE 0 END ), 0) KIN_2, NVL(SUM( CASE WHEN UMST.NYURYOKUMEISAIFLG = '1' THEN UMST.KIN ELSE 0 END ), 0) KIN, CASE WHEN SKSM.KAISHUHOHOKBN = '7' THEN NVL(SUM( CASE WHEN UMST.NYURYOKUMEISAIFLG = '1' THEN UMST.SHOHITAXKIN ELSE 0 END ), 0) ELSE NVL(SUM( CASE WHEN UMST.NYURYOKUMEISAIFLG = '1' THEN UMST.SHOHITAXKIN + UMST.SANKOUSHOHITAXKIN ELSE 0 END ), 0) END SHOHITAXKIN, CASE WHEN SKSM.KAISHUHOHOKBN = '7' THEN NVL(SUM( CASE WHEN UMST.NYURYOKUMEISAIFLG = '1' THEN UMST.KIN + UMST.SHOHITAXKIN ELSE 0 END ), 0) ELSE NVL(SUM( CASE WHEN UMST.NYURYOKUMEISAIFLG = '1' THEN UMST.KIN + UMST.SHOHITAXKIN + UMST.SANKOUSHOHITAXKIN ELSE 0 END ), 0) END TAXKOMIURIKEIKIN FROM S02M013T TKSM INNER JOIN S06T001T URGT ON TKSM.APKIHONCD = URGT.APKIHONCD AND TKSM.SHOPCD = URGT.SHOPCD AND TKSM.TOKUISAKICD = URGT.TOKUISAKICD INNER JOIN S06T002T UMST ON URGT.APKIHONCD = UMST.APKIHONCD AND URGT.SHOPCD = UMST.SHOPCD AND URGT.URIDNPYNO = UMST.URIDNPYNO AND URGT.EDANO = UMST.EDANO INNER JOIN S02M017T SKSM ON SKSM.APKIHONCD = TKSM.APKIHONCD AND SKSM.SHOPCD = TKSM.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD LEFT JOIN S02M006T SYKM_1 ON SYKM_1.APKIHONCD = '000' AND SYKM_1.SHOPCD = '000' AND SYKM_1.RCRDKBN = 'M' AND SYKM_1.SETTEINO = '096' AND SYKM_1.SETTEICD = '1' LEFT JOIN S02M006T SYKM_2 ON SYKM_2.APKIHONCD = '000' AND SYKM_2.SHOPCD = '000' AND SYKM_2.RCRDKBN = 'M' AND SYKM_2.SETTEINO = '096' AND SYKM_2.SETTEICD = '2' LEFT JOIN S02M006T SYKM_5 ON SYKM_5.APKIHONCD = '000' AND SYKM_5.SHOPCD = '000' AND SYKM_5.RCRDKBN = 'M' AND SYKM_5.SETTEINO = '096' AND SYKM_5.SETTEICD = '3' LEFT JOIN S01M004T CONM ON SKSM.KAISHUHOHOKBN = CONM.SETTEIATAI AND CONM.CONDITIONID = 'CN160' WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TKSM.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR} AND (