SELECT * FROM ( SELECT * FROM ( SELECT URGT.URIDD YMD, UMST.SHNCD SHNCD, SHMV.GENZSHNNMRYAKUSHO GENZSHNNMRYAKUSHO, SHMV.SHINSHNNMRYAKUSHO SHINSHNNMRYAKUSHO, SHMV.SHNNMKIRIKAEDD SHNNMKIRIKAEDD, SHMV.IRO IRO, SHMV.SZNM SZNM, UMST.KATASIKI KATASIKI, SYKM.MOJISETTEIATAI KEIJOKBNNM, UMST.SURYO SURYO, SHMV.URITRTSKITANINM URITRTSKITANINM, SHMV.URIIRISU URIIRISU, NVL(UMST.SURYO,0) * NVL(SHMV.URIIRISU,0) SOKAZU, NVL(UMST.UNT,0) UNT, NVL(UMST.KIN,0) KIN, ( SELECT SHZK.SHOHITAX FROM S02M091T SHZK WHERE UMST.TAXKBN = SHZK.TAXKBN AND URGT.URIDD >= SHZK.TEKIYOSTRTDD AND URGT.URIDD <= SHZK.TEKIYOSHRYDD AND SHZK.YUKOKBN = '1' ) AS TAXRATE, UMST.NYURYOKUMEISAIFLG NYURYOKUMEISAIFLG, NVL(UMST.SHOHITAXKIN,0) SHOHITAXKIN, NVL(UMST.SANKOUSHOHITAXKIN,0) SANKOUSHOHITAXKIN, 0 NYKNKIN, UMST.MEISAIBIKO BIKO, UMST.URIDNPYNO PYNO, URGT.EDANO EDANO, UMST.URIDNPYMEISAINO MEISAINO, URGT.TOKUISAKICD TOKUISAKICD, TKSM.TOKUISAKINMN1 TOKUISAKINMN1, UMST.INPTSYSTMYMD INPTSYSTMYMD, UMST.INPTSYSTMJIKAN INPTSYSTMJIKAN, UMST.TOSHAAPKIHONCD TOSHAAPKIHONCD, UMST.TOSHASHOPCD TOSHASHOPCD, UMST.TOSHACD TOSHACD, TTSM.TNSHAMEI TNSHAMEI, URGT.SKYSHOOTPTARINASHIKBN SKYSHOOTPTARINASHIKBN, NULL NYUKINKINDNM, YHPT.URIAGE_POINT URIPOINT, YHPT.TOKUBETSU_POINT TKBTPOINT, YHPT.POINT_WAKU POINTUTWK, NVL(YHPT.URIAGE_POINT,0) + NVL(YHPT.TOKUBETSU_POINT,0) SMPOINT, YHPT.POINT_RENKEI_DD POINTRENKEIDD FROM S06T001T URGT INNER JOIN S02M013T TKSM ON TKSM.APKIHONCD = URGT.APKIHONCD AND TKSM.SHOPCD = URGT.SHOPCD AND TKSM.TOKUISAKICD = URGT.TOKUISAKICD INNER JOIN S06T002T UMST ON URGT.APKIHONCD = UMST.APKIHONCD AND URGT.SHOPCD = UMST.SHOPCD AND URGT.URIDNPYNO = UMST.URIDNPYNO AND URGT.EDANO = UMST.EDANO
INNER JOIN S07T006T SMRT ON SMRT.APKIHONCD = URGT.APKIHONCD AND SMRT.SHOPCD = URGT.SHOPCD AND SMRT.SKYSAKICD = URGT.SKYSAKICD AND SMRT.DNPYNO = URGT.URIDNPYNO AND SMRT.URINYKNKBN = '0' INNER JOIN S07T001T SZDT ON SMRT.APKIHONCD = SZDT.APKIHONCD AND SMRT.SHOPCD = SZDT.SHOPCD AND SMRT.SKYSAKICD = SZDT.SKYSAKICD AND SMRT.SKYSHONO = SZDT.SKYSHONO AND SMRT.SKYSHONOEDANO = SZDT.SKYSHONOEDANO AND SZDT.RENBAN = #{renban,jdbcType=VARCHAR} AND SZDT.YUKOKBN = '1'
LEFT OUTER JOIN S02V001T SHMV ON UMST.APKIHONCD = SHMV.APKIHONCD AND UMST.SHOPCD = SHMV.SHOPCD AND UMST.SHNCD = SHMV.SHNCD LEFT OUTER JOIN S06T002T UMST2 ON UMST.APKIHONCD = UMST2.APKIHONCD AND UMST.SHOPCD = UMST2.SHOPCD AND UMST.URIDNPYNO = UMST2.URIDNPYNO AND UMST.EDANO = UMST2.EDANO AND UMST.URIDNPYMEISAINO = UMST2.URIDNPYMEISAINO AND UMST.STSHNCD = UMST2.SHNCD AND '5' = UMST2.TAXKBN LEFT OUTER JOIN S02M006T SYKM ON '000' = SYKM.APKIHONCD AND '000' = SYKM.SHOPCD AND '009' = SYKM.SETTEINO AND 'M' = SYKM.RCRDKBN AND UMST.KEIJOKBN = SYKM.SETTEICD LEFT OUTER JOIN S02M003T TTSM ON UMST.TOSHAAPKIHONCD = TTSM.APKIHONCD AND UMST.TOSHASHOPCD = TTSM.SHOPCD AND UMST.TOSHACD = TTSM.TNSHACD LEFT OUTER JOIN ( SELECT T1.APKIHONCD, T1.SHOPCD, T1.URIDNPYNO, T2.URIDNPYMEISAINO, T2.URIDNPYMEISAIEDANO, SUM(CASE WHEN T2.POINTKIND = '1' THEN NVL(T2.POINTSU, 0) ELSE 0 END) AS URIAGE_POINT, SUM(CASE WHEN T2.POINTKIND IN ('2','10','20','23','24','25') THEN NVL(T2.POINTSU, 0) ELSE 0 END) AS TOKUBETSU_POINT, MAX(CASE WHEN T2.POINTKIND IN ('1','2','10','20','23','24','25') THEN NULLIF(T2.POINTMYAQUARENKEIDD, '') ELSE NULL END) AS POINT_RENKEI_DD, LISTAGG( CASE WHEN T2.POINTKIND IN ('2','10') THEN 'まとめ買い:' || TO_CHAR(NVL(T2.POINTSU, 0)) WHEN T2.POINTKIND = '20' THEN '入会時特典:' || TO_CHAR(NVL(T2.POINTSU, 0)) WHEN T2.POINTKIND = '23' THEN '配達日:' || TO_CHAR(NVL(T2.POINTSU, 0)) WHEN T2.POINTKIND = '24' THEN '時間なし:' || TO_CHAR(NVL(T2.POINTSU, 0)) WHEN T2.POINTKIND = '25' THEN 'MyAqua注文:' || TO_CHAR(NVL(T2.POINTSU, 0)) ELSE NULL END, ',' ) WITHIN GROUP (ORDER BY T2.POINTKIND) AS POINT_WAKU FROM S20T001T T1 INNER JOIN S20T002T T2 ON T1.APKIHONCD = T2.APKIHONCD AND T1.SHOPCD = T2.SHOPCD AND T1.KANRINO = T2.KANRINO GROUP BY T1.APKIHONCD, T1.SHOPCD, T1.URIDNPYNO, T2.URIDNPYMEISAINO, T2.URIDNPYMEISAIEDANO ) YHPT ON YHPT.APKIHONCD = UMST.APKIHONCD AND YHPT.SHOPCD = UMST.SHOPCD AND YHPT.URIDNPYNO = UMST.URIDNPYNO AND YHPT.URIDNPYMEISAINO = UMST.URIDNPYMEISAINO AND YHPT.URIDNPYMEISAIEDANO = UMST.URIDNPYMEISAIEDANO WHERE
URGT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND URGT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND URGT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR} AND URGT.SKYSHIMEDYDM = #{shimedydm,jdbcType=VARCHAR} AND URGT.SKYSHIMEDD = #{shimedd,jdbcType=VARCHAR}
TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TKSM.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR} AND ( URGT.SKYPRCSJISSIDD = '00000000' OR URGT.SKYPRCSJISSIDD = 'DAIBIKI' )
AND ( TKSM.TOKUISAKICD IN
${tokuisakicd}
)
AND URGT.YUKOKBN = '1'
AND URGT.SKYSHOOTPTARINASHIKBN = '0'
AND ( UMST.NYURYOKUMEISAIFLG = '1' OR ( UMST.NYURYOKUMEISAIFLG = '0' AND UMST2.URIDNPYNO IS NOT NULL ) ) UNION ALL SELECT NMST.NYKNDD YMD, NULL SHNCD, NULL GENZSHNNMRYAKUSHO, NULL SHINSHNNMRYAKUSHO, NULL SHNNMKIRIKAEDD, NULL IRO, NULL SZNM, NULL KATASIKI, NULL KEIJOKBNNM, NULL SURYO, NULL URITRTSKITANINM, NULL URIIRISU, NULL SOKAZU, 0 UNT, 0 KIN, NULL TAXRATE, NULL NYURYOKUMEISAIFLG, 0 SHOHITAXKIN, 0 SANKOUSHOHITAXKIN, NVL(NMST.NYKNKIN, 0) + NVL(NMST.NEBIKIKIN,0) + NVL(NMST.TESURYO,0) NYKNKIN, NMST.BIKO BIKO, NMST.DNPYNO PYNO, NULL EDANO, 1 MEISAINO, TKSM.TOKUISAKICD TOKUISAKICD, TKSM.TOKUISAKINMN1 TOKUISAKINMN1, NMST.INPTSYSTMYMD INPTSYSTMYMD, NMST.INPTSYSTMJIKAN INPTSYSTMJIKAN, NMST.TOSHAAPKIHONCD TOSHAAPKIHONCD, NMST.TOSHASHOPCD TOSHASHOPCD, NMST.TOSHACD TOSHACD, TTSM.TNSHAMEI TNSHAMEI, NMST.SKYSHOOTPTARINASHIKBN SKYSHOOTPTARINASHIKBN, SYKM.MOJISETTEIATAI NYUKINKINDNM, NULL URIPOINT, NULL TKBTPOINT, NULL POINTUTWK, NULL SMPOINT, NULL POINTRENKEIDD FROM S10T001T NMST INNER JOIN S02M013T TKSM ON TKSM.APKIHONCD = NMST.APKIHONCD AND TKSM.SHOPCD = NMST.SHOPCD AND TKSM.TOKUISAKICD = NMST.TOKUISAKICD
INNER JOIN S07T006T SMRT ON SMRT.APKIHONCD = NMST.APKIHONCD AND SMRT.SHOPCD = NMST.SHOPCD AND SMRT.SKYSAKICD = NMST.SKYSAKICD AND SMRT.DNPYNO = NMST.DNPYNO AND SMRT.NYKNDNPYNOEDANO = NMST.NYKNDNPYNOEDANO AND SMRT.URINYKNKBN = '1' INNER JOIN S07T001T SZDT ON SMRT.APKIHONCD = SZDT.APKIHONCD AND SMRT.SHOPCD = SZDT.SHOPCD AND SMRT.SKYSAKICD = SZDT.SKYSAKICD AND SMRT.SKYSHONO = SZDT.SKYSHONO AND SMRT.SKYSHONOEDANO = SZDT.SKYSHONOEDANO AND SZDT.RENBAN = #{renban,jdbcType=VARCHAR} AND SZDT.YUKOKBN = '1'
INNER JOIN S02M017T SKSM ON TKSM.APKIHONCD = SKSM.APKIHONCD AND TKSM.SHOPCD = SKSM.SHOPCD AND TKSM.SKYSAKICD = SKSM.SKYSAKICD
LEFT OUTER JOIN S02M003T TTSM ON NMST.TOSHAAPKIHONCD = TTSM.APKIHONCD AND NMST.TOSHASHOPCD = TTSM.SHOPCD AND NMST.TOSHACD = TTSM.TNSHACD LEFT OUTER JOIN S02M006T SYKM ON '000' = SYKM.APKIHONCD AND '000' = SYKM.SHOPCD AND '050' = SYKM.SETTEINO AND 'M' = SYKM.RCRDKBN AND NMST.NYKNKIND = SYKM.SETTEICD WHERE NMST.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND NMST.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND NMST.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND NMST.SKYSHIMEDYDM = #{shimedydm,jdbcType=VARCHAR} AND NMST.SKYSHIMEDD = #{shimedd,jdbcType=VARCHAR}
AND NMST.SKYSHIMEDYDM IS NULL AND NMST.SKYSHIMEDD IS NULL
AND ( TKSM.TOKUISAKICD IN
${tokuisakicd}
)
AND NMST.YUKOKBN = '1'
AND NMST.SKYSHOOTPTARINASHIKBN = '0'
) ORDER BY YMD, PYNO, MEISAINO ) WHERE ROWNUM <= #{rownum}

